import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const fakeCreate = (product) => new Promise((res) => setTimeout(() => res({ ...product, saved: true }), 200));

function App() {
  const [items, setItems] = useState([]);

  function add() {
    const temp = { id: "t" + (items.length + 1), name: "Чихэвч", status: "..." };
    setItems((prev) => [...prev, temp]); // optimistic: шууд нэмнэ
    fakeCreate(temp).then((saved) => {
      setItems((prev) => prev.map((x) => (x.id === temp.id ? { ...x, status: "✓" } : x)));
    });
  }

  return (
    <View style={styles.s}>
      {items.map((it) => (
        <View key={it.id} style={styles.row}>
          <Text testID="row">{it.name}</Text>
          <Text testID="status" style={styles.status}>{it.status}</Text>
        </View>
      ))}
      <Pressable nativeID="add" style={styles.btn} onPress={add}><Text style={styles.btnText}>Сагслах</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16, gap: 8 },
  row: { flexDirection: "row", justifyContent: "space-between", paddingVertical: 10, borderBottomWidth: 1, borderColor: "#e2e8f0" },
  status: { color: "#16a34a", fontWeight: "bold" },
  btn: { backgroundColor: "#2563eb", padding: 12, borderRadius: 10, alignItems: "center", marginTop: 12 },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
